import{_ as r,o as a,c as p,a3 as t}from"./chunks/framework.BwzYn71E.js";const c=JSON.parse('{"title":"友情链接","description":"","frontmatter":{"translationSource":{"title":"友情链接","archivedAt":"2026-10-31","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=cuRlnn75Kga51BX2KAlOuD","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/related-links"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/related-links"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/related-links"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/related-links"}]]},"headers":[],"relativePath":"zh/related-links.md","filePath":"zh/page-cuRlnn75Kga51BX2KAlOuD.md"}'),n={name:"zh/related-links.md"};function l(i,e,o,d,f,h){return a(),p("div",null,[...e[0]||(e[0]=[t('<div class="logistics-content"><h1 id="友情链接" tabindex="-1">友情链接 <a class="header-anchor" href="#友情链接" aria-label="Permalink to &quot;友情链接&quot;">​</a></h1><blockquote><p>源页面 ID：<code>cuRlnn75Kga51BX2KAlOuD</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=cuRlnn75Kga51BX2KAlOuD" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p>如无特殊说明，xx群总是指QQ群群号。如有推荐，可以在我们的QQ群中说明。游客可以评论评价。</p><p><a href="https://factory.ef.yituliu.cn/aef" target="_blank" rel="noreferrer">终末地量化计算器</a> 反馈群：1071155059</p><p>factory.ef.yituliu.cn/aef</p><p>图形化产线分配、产物生产消耗计算，你群群友必备工具，可惜不足之处还有很多。</p><p>（非常好用，省去我很多草稿纸，要是能帮我取整就好了，1.25台机器之类的经常无法直接落地）</p><p><a href="http://fz.wiki" target="_blank" rel="noreferrer">fz终末地wiki</a></p><p>fz.wiki</p><p>目前最好的玩家共创wiki</p><p>（哦哦！地图好用！不用花钱买道具找宝箱了）</p><p><a href="https://warfarin.wiki/cn" target="_blank" rel="noreferrer">华法琳Wiki</a> discord：<a href="https://discord.gg/RjAN7VXxGX" target="_blank" rel="noreferrer">RjAN7VXxGX</a></p><p>warfarin.wiki/cn</p><p>如今依旧有不错的更新频率的wiki。</p><p>（界面不太适配手机）</p><p><a href="http://end.fffdan.com" target="_blank" rel="noreferrer">宏山档案局</a></p><p>end.fffdan.com</p><p>群友特供wiki，提供天师数据库API的使用范例。最近有点比较难访问。</p><p>（界面不太适配手机，但它可以听音乐啊）</p><p><a href="http://endfield-assets.fffdan.com/scalar/" target="_blank" rel="noreferrer">天师数据库</a></p><p>endfield-assets.fffdan.com/scalar/</p><p>终末地数据表与图标图像数据获取API，提供ai使用的skill，随时可供使用。相比akedata，提供了数据表的表</p><p><a href="http://akedata.wiki" target="_blank" rel="noreferrer">终末地数据库</a></p><p>akedata.wiki</p><p>akewiki，较新的wiki，同样是解包数据，相比天师数据库的数据库服务更快。</p><p><a href="https://ef.yituliu.cn/" target="_blank" rel="noreferrer">终末地一图流</a> 开发群：696486169</p><p>ef.yituliu.cn</p><p>商店/礼包性价比计算、攒抽计算器、礼物查询、选剑演武计算器，此外还提供每版本一套的毕业基建蓝图，虽然不知道一图是什么的一图，但是功能足够繁多。</p><p><a href="https://maaend.com/" target="_blank" rel="noreferrer">MaaEnd</a> 用户群：1062010346 开发群：1072587329</p><p>maaend.com</p><p>依靠脚本完成日常，非常好用。</p><p><a href="https://end.canmoe.com/zh-CN" target="_blank" rel="noreferrer">CEP 终末地规划器</a> 群：1045523485</p><p>end.canmoe.com/zh-CN</p><p>基质规划、精锻规划、养成规划，以规划为主，还提供干员、武器、装备的查看和游戏文案的查询功能，界面大方美观，内容相对其他wiki可能有一定缺失。</p><p><a href="http://zipliner.org" target="_blank" rel="noreferrer">Zipliner</a></p><p>zipliner.org</p><p>滑索地图站，简洁明了。</p><p><a href="https://zmdjj.pythonanywhere.com/" target="_blank" rel="noreferrer">群友做的阅读网站</a></p><p>zmdjj.pythonanywhere.com</p><p>暂时没有名字，用处的话，用来防止腾讯文档抽风，给的链接瞎跳转。持续更新中，有望成为任务板的拓展甚至代替</p><p><a href="https://kokobird28144.github.io/endfield-skydoc/" target="_blank" rel="noreferrer">任务板镜像站：Endfield-Skydoc</a></p><p>kokobird28144.github.io/endfield-skydoc</p><p>目前由 kokobird 维护，定期从主文档抓取，翻译成英文（主要目的）并更新</p><p><a href="https://dige.aunly.cn/?lang=zh" target="_blank" rel="noreferrer">D.I.G.E</a> 群：1084531249</p><p>dige.aunly.cn/?lang=zh</p><p>电力分流模拟求解器，依旧震荡发电，但是添加了模拟能力防止断电。</p><p><a href="https://mikunyaaa.github.io/endfield-calculator/" target="_blank" rel="noreferrer">电力分流计算器</a></p><p>mikunyaaa.github.io/endfield-calculator</p><p>电力分流模拟求解器，精简小巧。</p><p><a href="http://wiki.skland.com" target="_blank" rel="noreferrer">森空岛</a></p><p>wiki.skland.com</p><p>鹰角官方社区，提供很差的wiki，实时位置地图，干员养成统计等功能，优点在于更新有时比较超前，官方发布内容可以随时查看。</p><p><a href="https://www.end-axis.com/timeline" target="_blank" rel="noreferrer">终末地排轴器-排轴终端</a> 交流群：1125518981</p><p>www.end-axis.com/timeline</p><p>战斗排轴器，群友不太关注战斗的一般不用（生电玩家打不过蠹虫.gif），此外也有配队推荐（排轴广场）</p><p><a href="http://ef.exgamer.top" target="_blank" rel="noreferrer">超级玩家</a></p><p>ef.exgamer.top</p><p>来自b站up 半壁_Yakoo 的小工具，目前最特别的是缘缘庄厨房规划助手。</p><p><a href="http://rahoo.online/" target="_blank" rel="noreferrer">封面生成器</a></p><p>rahoo.online</p><p>来自b站up 拉乎 的工具集，有各类常见的快速素材生成方案，一些常见的配队介绍封面等。</p><p><a href="http://ignoredone.space" target="_blank" rel="noreferrer">ignoredone&#39;s space</a></p><p>ignoredone.space</p><p>来自b站up ignoredone 的类个人网页，这位是粥味设计的大佬，网站提供了作品、素材等，也提供了学习工程的路径。</p><p><a href="https://beta.enka.network/endfield/aic/" target="_blank" rel="noreferrer">EnKAD终末地基建模拟器</a> discord：<a href="https://discord.gg/gvXnJhBvWG" target="_blank" rel="noreferrer">gvXnJhBvWG</a> mcp仓库：<a href="https://github.com/EugW/enkad_mcp/tree/main" target="_blank" rel="noreferrer">enkad_mcp</a></p><p>beta.enka.network/endfield/aic</p><p>可以快速得到结果的基建模拟器，可以在一定程度上模拟优先输出现象，目前最接近实际效果的模拟器。</p><p><a href="https://endfield.amiyabot.com/" target="_blank" rel="noreferrer">终末地工业系统仿真器</a></p><p>endfield.amiyabot.com</p><p>又叫做amiyabot仿真器，但是仓库其实叫IndustrialPlanner，界面更加整洁，可以手动设置优先级，可以边运行边改动，但是得到结果不快，而且性能消耗较大，同样无法模拟复杂限流器。有自动布局功能。</p><p><a href="http://opendfieldmap.cn" target="_blank" rel="noreferrer">终末地地图集</a> 交流群：1075906513 discord：<a href="https://discord.gg/BFMAKZSUG7" target="_blank" rel="noreferrer">BFMAKZSUG7</a></p><p>opendfieldmap.cn</p><p>相当详细的地图，可以使用maa等工具检查有哪些档案未收集，不过性能消耗有些高。</p><p><a href="https://endfieldtools.dev/" target="_blank" rel="noreferrer">Arknights Endfield Tools &amp; Database</a></p><p>？</p><p><a href="http://endfield.wiki.gg" target="_blank" rel="noreferrer">Endfield Talos Wiki</a></p><p>？</p></div>',1)])])}const s=r(n,[["render",l]]);export{c as __pageData,s as default};
